ByteVector extract_subrange(uint index, uint length) {
    if (index >= data.size()) {
        return ByteVector();
    }

    uint end_index = std::min(index + length, static_cast<uint>(data.size()));
    ByteVector result;
    for (uint i = index; i < end_index; ++i) {
        result.push_back(data[i]);
    }
    return result;
}

ByteVector extract_subrange_from_vector(const ByteVector& data, uint index, uint length) {
    if (index >= data.size()) {
        return ByteVector();
    }

    uint end_index = std::min(index + length, static_cast<uint>(data.size()));
    ByteVector subvector(data.begin() + index, data.begin() + end_index);
    return subvector;
}

ByteVector extractSubrangeFromVector(uint index, uint length) {
    if (index >= data.size()) {
        return ByteVector();
    }

    uint endPos = index + length;
    if (endPos > data.size()) {
        endPos = data.size();
    }

    ByteVector subVector;
    for (uint i = index; i < endPos; ++i) {
        subVector.push_back(data[i]);
    }

    return subVector;
}

ByteVector extractSubrange(uint index, uint length) {
    if (index >= data.size()) {
        return ByteVector();
    }

    uint endPos = index + length;
    if (endPos > data.size()) {
        endPos = data.size();
    }

    return ByteVector(data.begin() + index, data.begin() + endPos);
}

ByteVector extractSubrange(uint index, uint length) const {
    if (index >= data.size()) {
        return ByteVector();
    }

    uint endPos = index + length;
    if (endPos > data.size()) {
        endPos = data.size();
    }

    ByteVector result;
    result.data.insert(result.data.begin(), data.begin() + index, data.begin() + endPos);
    return result;
}
